from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class BasicCellsSummaryAdministrativeStateASMV1(SchemaObject):
    locked = SchemaField(name="locked")
    shutting_down = SchemaField(name="shutting down")
    unlocked = SchemaField(name="unlocked")

    def __init__(self, locked, shutting_down, unlocked):
        self.locked = locked
        self.shutting_down = shutting_down
        self.unlocked = unlocked
        super(BasicCellsSummaryAdministrativeStateASMV1, self).__init__()


class BasicCellsSummaryOperationalStateASMV1(SchemaObject):
    disabled = SchemaField(name="disabled")
    enabled = SchemaField(name="enabled")

    def __init__(self, disabled, enabled):
        self.disabled = disabled
        self.enabled = enabled
        super(BasicCellsSummaryOperationalStateASMV1, self).__init__()


class BasicCellsSummaryBlokingStateASMV1(SchemaObject):
    blocked = SchemaField(name='blocked')
    unblocked = SchemaField(name='unblocked')
    blocking = SchemaField(name='blocking')
    unblocking = SchemaField(name='unblocking')

    def __init__(self, blocked, unblocked, blocking, unblocking):
        self.blocked = blocked
        self.unblocked = unblocked
        self.blocking = blocking
        self.unblocking = unblocking

        super(BasicCellsSummaryBlokingStateASMV1, self).__init__()


class BasicCellsSummaryASMV1(SchemaObject):
    administrative_state = SchemaField(name="administrativeState", klass=BasicCellsSummaryAdministrativeStateASMV1)
    operational_state = SchemaField(name="operationalState", klass=BasicCellsSummaryOperationalStateASMV1)
    blocking_state = SchemaField(name="blockingState", klass=BasicCellsSummaryBlokingStateASMV1, optional=True)

    def __init__(self, administrative_state, operational_state, blocking_state):
        self.administrative_state = administrative_state
        self.operational_state = operational_state
        self.blocking_state = blocking_state
        super(BasicCellsSummaryASMV1, self).__init__()


class AvailabilityStatusASMV1(SchemaObject):
    degraded = SchemaField(name="degraded")
    dependency = SchemaField(name="dependency")
    failed = SchemaField(name="failed")
    in_test = SchemaField(name="in test")
    log_full = SchemaField(name="log full")
    not_installed = SchemaField(name="not installed")
    off_duty = SchemaField(name="off duty")
    off_line = SchemaField(name="off line")
    on_line = SchemaField(name="on line")
    power_off = SchemaField(name="power off")

    def __init__(self, degraded, dependency, failed, in_test, log_full,
                 not_installed, off_duty, off_line, on_line, power_off):
        self.degraded = degraded
        self.dependency = dependency
        self.failed = failed
        self.in_test = in_test
        self.log_full = log_full
        self.not_installed = not_installed
        self.off_duty = off_duty
        self.off_line = off_line
        self.on_line = on_line
        self.power_off = power_off

        super(AvailabilityStatusASMV1, self).__init__()


class VDUCellsSummaryASMV1(SchemaObject):
    basic_cells_summary = SchemaField(name="basicCellsSummary", klass=BasicCellsSummaryASMV1)
    availability_status = SchemaField(name="availabilityStatus", klass=AvailabilityStatusASMV1)

    def __init__(self, basic_cells_summary, availability_status):
        self.basic_cells_summary = basic_cells_summary
        self.availability_status = availability_status
        super(VDUCellsSummaryASMV1, self).__init__()
